{
  "name": "@amykit/plugin-prove",
  "version": "0.7.1",
  "description": "Proves a phase against the real system: one workflow walks the scenario each brief settled, through the operations the mounted plugins offer.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/prove"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "workflow.mmd"
  ],
  "amy": {
    "about": "Use it as the proving phase of a project, once a brief has settled the scenario the work must pass. It is a workflow that walks that scenario against the real system through the operations mounted plugins offer, such as agent-browser, agent-desktop and terminal, and records a proof. It needs file-brief-store and a notifier; mount command for the resources a scenario runs against and the code digest, and a conversation so it can ask a person to make a fixture hold."
  },
  "dependencies": {
    "@amykit/core": "^0.7.1",
    "yaml": "^2.8.1",
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "@amykit/plugin-command": "^0.7.1",
    "@amykit/test-fixtures": "^0.1.0",
    "fast-check": "^4.10.2"
  }
}

import { Assertion, at, same } from "./scenario.js";

/**
 * How one step ended: with an output, failed, or unsupported — a step the
 * run could not evaluate at all, which is not a pass and is not a failure
 * of the work either.
 */
export type StepResult =
  | { readonly status: "done"; readonly output: unknown }
  | { readonly status: "failed"; readonly why: string }
  | { readonly status: "unsupported"; readonly why: string };

/**
 * An assertion's status. `unsupported` is a state of its own: an assertion
 * the harness could not evaluate is the thing most often counted as a pass.
 */
export type AssertionStatus = "passed" | "failed" | "unsupported";

export interface AssertionResult {
  readonly id: string;
  readonly criterion?: string;
  readonly status: AssertionStatus;
  readonly why?: string;
}

/**
 * An output that says it could not settle what it was asked — a UI check
 * neither the trees nor the pixels decided, and no agent could — is
 * unsupported, whatever else it carries.
 */
function unsupportedIn(output: unknown): string | undefined {
  if (typeof output !== "object" || output === null) return undefined;
  const { status, why } = output as { status?: unknown; why?: unknown };
  return status === "unsupported" ? (typeof why === "string" ? why : "the operation could not settle it") : undefined;
}

/** Judges one assertion against what the run's steps produced. */
export function evaluate(assertion: Assertion, results: Readonly<Record<string, StepResult>>): AssertionResult {
  const named = { id: assertion.id, ...(assertion.criterion ? { criterion: assertion.criterion } : {}) };
  const result = Object.hasOwn(results, assertion.step) ? results[assertion.step] : undefined;
  if (!result) return { ...named, status: "unsupported", why: `the step \`${assertion.step}\` never ran, so nothing could evaluate it` };
  if (result.status !== "done") return { ...named, status: result.status, why: `the step \`${assertion.step}\` ${result.status === "failed" ? "failed" : "could not be evaluated"}: ${result.why}` };
  const unsettled = unsupportedIn(result.output);
  if (unsettled !== undefined) return { ...named, status: "unsupported", why: `the step \`${assertion.step}\` could not settle it: ${unsettled}` };
  const found = at(result.output, assertion.path);
  if (!found.found) return { ...named, status: "unsupported", why: `the output of \`${assertion.step}\` carries no \`${assertion.path}\` to evaluate` };
  if (assertion.equals === undefined) return { ...named, status: "passed" };
  return same(found.value, assertion.equals)
    ? { ...named, status: "passed" }
    : { ...named, status: "failed", why: `\`${assertion.path ?? assertion.step}\` is ${JSON.stringify(found.value)}, not ${JSON.stringify(assertion.equals)}` };
}

/** Whether a run's assertions complete the proof: every one passed, none unsupported. */
export function holds(results: readonly AssertionResult[]): boolean {
  return results.length > 0 && results.every((one) => one.status === "passed");
}

/** What blocks completion, one line per assertion, naming it and why. */
export function blocking(results: readonly AssertionResult[]): string[] {
  return results.filter((one) => one.status !== "passed").map((one) => `\`${one.id}\` is ${one.status}: ${one.why ?? "no reason given"}`);
}

import { Plan, WorkRecord, act, advance, settled, wait } from "@amykit/core";
import { AssertionResult, StepResult, blocking, evaluate, holds } from "./assertions.js";
import type { Resource } from "./resources.js";
import { Fixture, OperationCall, Scenario, Step } from "./scenario.js";

export type ProveState = "READING" | "LEASING" | "PREPARING" | "RUNNING" | "ASKING" | "PROVEN" | "refused";

/** Where a person was asked, and about what: a human step, or a fixture nothing could make hold. */
export interface Asking {
  readonly step?: string;
  readonly fixture?: string;
  readonly question: string;
  readonly askedAt: string;
  readonly deadlineAt: string;
  /** The work's thread, when a conversation is mounted. */
  readonly thread?: string;
}

/** Everything the proving walk remembers about one run, between looks. */
export interface ProveRecord extends WorkRecord {
  state: ProveState;
  input?: { criteria?: string[]; priority?: number };
  /** The scenario, as the brief settled it when the run started. */
  scenario?: Scenario;
  briefRevision?: number;
  /** The resources this run holds a seat on. */
  held?: string[];
  /** The resources this run brought up. */
  up?: string[];
  /** The code digest the run proves, once read: null where there is no code. */
  digest?: string | null;
  prepared?: boolean;
  /** Why preparing failed, naming the resource and its check's output. */
  failed?: string;
  /** A fixture nothing could make hold, waiting for a person. */
  fixtureAsk?: { readonly fixture: string; readonly question: string };
  /** When the person asked to make each fixture hold has to have done it by: the first ask's deadline. */
  fixtureDeadlines?: Record<string, string>;
  results?: Record<string, StepResult>;
  /** The calls each agent step made this run, kept as its replay only if its assertions pass. */
  agentCalls?: Record<string, OperationCall[]>;
  /** When each wait-until step first checked, its deadline counted from there. */
  untilSince?: Record<string, string>;
  asking?: Asking;
  /** What the run proved, once it ended. */
  verdict?: { readonly assertions: readonly AssertionResult[]; readonly refused?: string };
}

export interface Observation {
  readonly unit: string;
  readonly scenario?: Scenario;
  readonly problems: readonly string[];
  readonly briefRevision: number;
  /** Seats this run held that are not its any more: it stopped renewing, and they expired. */
  readonly lost: readonly string[];
  /** The person's answer, while asking. */
  readonly reply?: { readonly author: string; readonly text: string; readonly at: string };
  readonly now: string;
}

export interface Policy {
  readonly resources: Readonly<Record<string, Resource>>;
  readonly fixtures: Readonly<Record<string, Fixture>>;
  readonly leaseTtlMs: number;
  readonly seatRetryMs: number;
  readonly askEveryMs: number;
  readonly fixtureDeadlineMs: number;
}

export type Effect =
  | { type: "lease" }
  | { type: "renew" }
  | { type: "prepare" }
  | { type: "run-step"; step: string }
  | { type: "ask"; step?: string; fixture?: string; question: string; deadlineMs: number }
  | { type: "give-up" }
  | { type: "finish"; outcome: "proven" | "refused"; why: string };

type Decision = (record: ProveRecord, observation: Observation, policy: Policy) => Plan;

/** The step the run takes next: the first with no result. */
export function nextStep(record: ProveRecord): Step | undefined {
  const done = record.results ?? {};
  return record.scenario?.steps.find((one) => !Object.hasOwn(done, one.id));
}

/**
 * The steps that keep a run from holding whatever its assertions say: one
 * that failed, or one nothing could evaluate, means the scenario did not
 * hold against the system, asserted on or not.
 */
export function stepsBlocking(record: ProveRecord): string[] {
  return Object.entries(record.results ?? {}).flatMap(([step, result]) => (result.status === "done" ? [] : [`the step \`${step}\` ${result.status === "failed" ? "failed" : "could not be evaluated"}: ${result.why}`]));
}

/** An end of the run: the move, and the effect that records the proof and lets go of what it held. */
function end(outcome: "PROVEN" | "refused", why: string, ...before: Effect[]): Plan {
  return advance(outcome, why, ...before, { type: "finish", outcome: outcome === "PROVEN" ? "proven" : "refused", why });
}

/** What the run proved: each assertion against the steps' results. */
export function verdictOf(record: ProveRecord): readonly AssertionResult[] {
  return (record.scenario?.assertions ?? []).map((one) => evaluate(one, record.results ?? {}));
}

/**
 * How long a run holding seats may wait between looks: never past half a
 * seat's life, or the look that renews it would come after it ran out.
 */
const holding = (policy: Policy, ms: number): number => Math.min(ms, Math.floor(policy.leaseTtlMs / 2));

const lostLease = (observation: Observation): Plan | undefined => (observation.lost.length > 0
  ? advance("LEASING", `the lease on ${observation.lost.map((one) => `\`${one}\``).join(", ")} ran out, so the run waits for a seat again`)
  : undefined);

export const decide = {
  READING: (_record, observation, policy) => observation.scenario
    ? advance("LEASING", `the brief names the scenario \`${observation.scenario.name}\``)
    : wait(policy.seatRetryMs, `the brief \`${observation.unit}\` names no scenario a run can walk: ${observation.problems.join("; ") || "it has none"}`),

  LEASING: (record, _observation, policy) => {
    const needed = record.scenario?.resources ?? [];
    const unknown = needed.filter((one) => !Object.hasOwn(policy.resources, one));
    if (unknown.length > 0) {
      return end("refused", `the scenario needs ${unknown.map((one) => `\`${one}\``).join(", ")}, which no configured resource is`);
    }
    const missing = needed.filter((one) => !(record.held ?? []).includes(one));
    if (missing.length === 0) return advance("PREPARING", needed.length > 0 ? `holds a seat on ${needed.map((one) => `\`${one}\``).join(", ")}` : "the scenario needs no resource");
    return wait(holding(policy, policy.seatRetryMs), `waiting for a seat on ${missing.map((one) => `\`${one}\``).join(", ")}`, { type: "lease" });
  },

  PREPARING: (record, observation, policy) => {
    const lost = lostLease(observation);
    if (lost) return lost;
    if (record.failed) return end("refused", record.failed);
    if (record.fixtureAsk) {
      // Asked again while it still does not hold, within the first ask's deadline.
      const { fixture, question } = record.fixtureAsk;
      const by = record.fixtureDeadlines?.[fixture];
      if (by && observation.now >= by) return end("refused", `nobody made the fixture \`${fixture}\` hold before ${by}`);
      const deadlineMs = by ? Date.parse(by) - Date.parse(observation.now) : policy.fixtureDeadlineMs;
      return advance("ASKING", `the fixture \`${fixture}\` cannot reach its state on its own`, { type: "ask", fixture, question, deadlineMs });
    }
    if (record.prepared) return advance("RUNNING", "the resources are up and every fixture holds");
    return act("bring the resources up and ensure the fixtures", { type: "prepare" });
  },

  RUNNING: (record, observation, policy) => {
    const lost = lostLease(observation);
    if (lost) return lost;
    const step = nextStep(record);
    if (!step) {
      const assertions = verdictOf(record);
      const broken = [...stepsBlocking(record), ...(holds(assertions) ? [] : blocking(assertions))];
      return broken.length === 0 ? end("PROVEN", `every step and assertion of \`${record.scenario?.name}\` passed`) : end("refused", broken.join("; "));
    }
    if (step.kind === "human") return advance("ASKING", `the step \`${step.id}\` asks a person`, { type: "ask", step: step.id, question: step.ask, deadlineMs: step.deadlineMs });
    const since = step.kind === "wait-until" ? record.untilSince?.[step.id] : undefined;
    if (step.kind === "wait-until" && since) {
      // The next check comes no later than the deadline, so a check past it
      // is the one that fails the step rather than one that passes late.
      const left = Date.parse(since) + step.deadlineMs - Date.parse(observation.now);
      return wait(holding(policy, Math.max(1, Math.min(step.everyMs, left))), `waiting until \`${step.operation}\` holds for \`${step.id}\``, { type: "run-step", step: step.id });
    }
    // A wait-until's first check is a look like its later ones: what costs an
    // attempt is a step that acts, not one that reads until the world agrees.
    if (step.kind === "wait-until") return act(`check \`${step.id}\``, { attempt: false }, { type: "run-step", step: step.id });
    return act(`run \`${step.id}\``, { type: "run-step", step: step.id });
  },

  ASKING: (record, observation, policy) => {
    const asking = record.asking;
    if (!asking) return advance(record.fixtureAsk ? "PREPARING" : "RUNNING", "nothing is being asked");
    // The deadline before the seats: a run nobody answered in time is over,
    // whether or not its seats outlived the wait, and an answer that came
    // after the deadline is not one in time however soon it is read.
    const reply = observation.reply && observation.reply.at <= asking.deadlineAt ? observation.reply : undefined;
    if (!reply && observation.now >= asking.deadlineAt) {
      return end("refused", `nobody answered \`${asking.step ?? asking.fixture}\` before ${asking.deadlineAt}`, { type: "give-up" });
    }
    const lost = lostLease(observation);
    if (lost) return lost;
    if (reply) {
      return asking.fixture
        ? advance("PREPARING", `${reply.author} made the fixture \`${asking.fixture}\` hold`)
        : advance("RUNNING", `${reply.author} answered \`${asking.step}\``);
    }
    return wait(holding(policy, policy.askEveryMs), `waiting on a person for \`${asking.step ?? asking.fixture}\``, { type: "renew" });
  },

  PROVEN: () => settled("the scenario held against the real system, and the proof is recorded"),
  refused: () => settled("the scenario did not hold, and what did not is recorded"),
} satisfies Record<ProveState, Decision>;

import type { Operated } from "@amykit/core";
import { Fixture, fixtureSchema, meets } from "./scenario.js";

/**
 * A fixture ensures a state rather than performing an action: it reads the
 * world first, acts only on what differs, and asks a person when it cannot.
 * Shared across scenarios, so it is configured once, not written per brief.
 */
export type Ensured =
  | { readonly holds: true; /** The operations it had to call, in order; none when the state already held. */ readonly acted: readonly string[] }
  | { readonly holds: false; readonly acted: readonly string[]; /** What a person is asked to make true. */ readonly ask: string };

/** Reads the fixtures a configuration names, refusing one that is not a fixture, by name. */
export function readFixtures(raw: Readonly<Record<string, unknown>>): Record<string, Fixture> {
  const fixtures: Record<string, Fixture> = {};
  for (const [name, value] of Object.entries(raw)) {
    const read = fixtureSchema.safeParse(value);
    if (!read.success) throw new Error(`the fixture \`${name}\` is not one: ${read.error.issues.map((issue) => `${issue.path.join(".")}: ${issue.message}`).join("; ")}`);
    fixtures[name] = read.data;
  }
  return fixtures;
}

export async function ensure(name: string, fixture: Fixture, operate: (id: string, input: unknown) => Promise<Operated>): Promise<Ensured> {
  const acted: string[] = [];
  for (const clause of fixture.ensure) {
    const read = await operate(clause.check.operation, clause.check.input);
    // A read that failed says nothing about the world: acting on it could
    // change a state that already held, so a person is asked instead.
    if (!read.ok) {
      return { holds: false, acted, ask: `the fixture \`${name}\` could not read \`${clause.check.operation}\` (${read.error.code}: ${read.error.message}): make sure it holds, then answer here` };
    }
    if (meets(read.output, clause.check.expect)) continue;
    if (!clause.act) {
      return { holds: false, acted, ask: `the fixture \`${name}\` needs \`${clause.check.operation}\` to hold, and nothing configured can make it hold: make it true, then answer here` };
    }
    const done = await operate(clause.act.operation, clause.act.input);
    acted.push(clause.act.operation);
    const again = done.ok ? await operate(clause.check.operation, clause.check.input) : done;
    if (!again.ok || !meets(again.output, clause.check.expect)) {
      const why = again.ok ? "it still does not hold" : `${again.error.code}: ${again.error.message}`;
      return { holds: false, acted, ask: `the fixture \`${name}\` ran \`${clause.act.operation}\` and \`${clause.check.operation}\` ${again.ok ? "still does not hold" : `failed (${why})`}: make it true, then answer here` };
    }
  }
  return { holds: true, acted };
}

export { configSchema, holderOf, leasesAt, needs, plugin, proofsAt } from "./plugin.js";
/** The unit a run proves is the core's to say, at any call depth; kept here for whoever imported it from prove. */
export { unitOf } from "@amykit/core";
export type { Settings } from "./plugin.js";
export { decide, nextStep, verdictOf } from "./decide.js";
export type { Asking, Effect, Observation, Policy, ProveRecord, ProveState } from "./decide.js";
export { blocking, evaluate, holds } from "./assertions.js";
export type { AssertionResult, AssertionStatus, StepResult } from "./assertions.js";
export { Leases } from "./lease.js";
export type { Claim, Claimed } from "./lease.js";
export { PROOFS_DIRECTORY, ProofStore } from "./proof.js";
export type { ProofRecord, Standing } from "./proof.js";
export { proofOperations, proofsOfScope } from "./operations.js";
export { bringUp, commandsNamed, readResources, takeDown } from "./resources.js";
export type { Resource } from "./resources.js";
export { ensure, readFixtures } from "./fixtures.js";
export type { Ensured } from "./fixtures.js";
export { SCENARIO_SECTION, checkScenario, readScenario, scenarioText } from "./scenario.js";
export type { Assertion, Expectation, Fixture, OperationCall, Scenario, Step } from "./scenario.js";
export { Replays, checkUntil, runAgent, runDeterministic } from "./steps.js";
export type { OfferedOperation, Replay, StepPorts } from "./steps.js";

import fs from "node:fs";
import path from "node:path";
import { type HeldLock, takeLock } from "@amykit/core";
import { segment } from "./names.js";

/**
 * Seats on a resource, shared by every project and profile on the machine.
 *
 * The work moves under the proof: two tickets in different phases may need
 * one account at once. A resource has a capacity; a run claims a seat before
 * its first step, and waits when it cannot. The next free seat goes by the
 * work's priority, and a holder that stops renewing loses its seat.
 *
 * Kept under Amy home rather than in a project's artifact root: one account
 * is one resource however many projects reach it, and each project's root is
 * its own.
 */

interface Seat {
  readonly priority: number;
  readonly expiresAt: number;
  /** When it first asked, kept so a seat given back waits where it waited. */
  readonly since?: number;
}

interface Waiter {
  readonly priority: number;
  /** When it first asked, for the order among equal priorities. */
  readonly since: number;
  /** A waiter that stops asking is forgotten, or it would hold the queue forever. */
  readonly expiresAt: number;
}

interface Ledger {
  holders: Record<string, Seat>;
  waiting: Record<string, Waiter>;
  /** The last holder, taking the resource down: no seat is given until it is down. */
  draining?: string;
}

export interface Claim {
  readonly resource: string;
  readonly capacity: number;
  /** Who holds the seat: the run's work id. */
  readonly holder: string;
  /** Higher goes first. */
  readonly priority: number;
  /** How long a seat lasts without a renewal. */
  readonly ttlMs: number;
}

export type Claimed =
  | { readonly held: true }
  | { readonly held: false; readonly holders: readonly string[]; readonly ahead: number };

/** How long a lock naming no process, an earlier version's half-made one, stands before its maker is taken for dead. */
const UNOWNED_STALE_MS = 10_000;
/** How long a claim waits for another process's lock before saying it stayed taken. */
const LOCK_PATIENCE_MS = 10_000;

export class Leases {
  constructor(
    private readonly root: string,
    private readonly now: () => Date = () => new Date(),
    private readonly patienceMs: number = LOCK_PATIENCE_MS,
  ) {}

  /**
   * Takes a seat, or joins the queue for one. A holder claiming again
   * renews; a waiter keeps its place in the queue by asking again.
   */
  claim(claim: Claim): Claimed {
    if (!Number.isInteger(claim.capacity) || claim.capacity < 1) throw new Error(`the resource \`${claim.resource}\` has a capacity of ${claim.capacity}; it needs at least one seat`);
    return this.locked(claim.resource, (ledger, now) => {
      const expiresAt = now + claim.ttlMs;
      if (ledger.holders[claim.holder]) {
        ledger.holders[claim.holder] = { priority: claim.priority, expiresAt };
        return { held: true };
      }
      const already = ledger.waiting[claim.holder];
      const since = already?.since ?? now;
      ledger.waiting[claim.holder] = { priority: claim.priority, since, expiresAt };
      const free = ledger.draining === undefined ? this.freeSeats(claim.capacity, Object.keys(ledger.holders).length) : 0;
      const ahead = queue(ledger).indexOf(claim.holder);
      if (ahead < free) {
        delete ledger.waiting[claim.holder];
        ledger.holders[claim.holder] = { priority: claim.priority, expiresAt, since };
        return { held: true };
      }
      return { held: false, holders: Object.keys(ledger.holders).sort(), ahead: ahead - Math.max(free, 0) };
    });
  }

  /** Extends a held seat; false when the seat was already lost. */
  renew(resource: string, holder: string, ttlMs: number): boolean {
    return this.locked(resource, (ledger, now) => {
      const seat = ledger.holders[holder];
      if (!seat) return false;
      ledger.holders[holder] = { ...seat, expiresAt: now + ttlMs };
      return true;
    });
  }

  /** Gives the seat back, or leaves the queue. */
  release(resource: string, holder: string): void {
    this.locked(resource, (ledger) => {
      delete ledger.holders[holder];
      delete ledger.waiting[holder];
      if (ledger.draining === holder) delete ledger.draining;
    });
  }

  /**
   * Whether this holder is the last one on the resource. When it is, it
   * keeps its seat and the resource drains — no seat is given — until its
   * `release`, so taking the resource down never pulls it from under a run
   * that just claimed it. Otherwise its seat is given back at once. A
   * holder whose seat ran out with nobody else on the resource is the last.
   */
  leaveLast(resource: string, holder: string, ttlMs: number): boolean {
    return this.locked(resource, (ledger, now) => {
      const others = Object.keys(ledger.holders).filter((one) => one !== holder);
      if (others.length === 0) {
        // A seat that ran out while nobody took it is still this run's to
        // take down: it holds the resource again while it drains.
        ledger.holders[holder] ??= { priority: 0, expiresAt: now + ttlMs };
        ledger.draining = holder;
        return true;
      }
      delete ledger.holders[holder];
      delete ledger.waiting[holder];
      return false;
    });
  }

  /** Who holds a seat now, expired seats left out. */
  holders(resource: string): string[] {
    const ledger = this.read(resource);
    const now = this.now().getTime();
    return Object.entries(ledger.holders).filter(([, seat]) => seat.expiresAt > now).map(([holder]) => holder).sort();
  }

  /** Who waits, in the order seats will go to them. */
  waiting(resource: string): string[] {
    const ledger = this.read(resource);
    expire(ledger, this.now().getTime());
    return queue(ledger);
  }

  holds(resource: string, holder: string): boolean {
    return this.holders(resource).includes(holder);
  }

  /** The seats left; a seam a property test plants a mutation in. */
  protected freeSeats(capacity: number, held: number): number {
    return capacity - held;
  }

  private file(resource: string): string {
    return path.join(this.root, `${segment(resource)}.json`);
  }

  private read(resource: string): Ledger {
    try {
      const parsed = JSON.parse(fs.readFileSync(this.file(resource), "utf-8")) as Partial<Ledger>;
      return { holders: parsed.holders ?? {}, waiting: parsed.waiting ?? {}, ...(parsed.draining ? { draining: parsed.draining } : {}) };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return { holders: {}, waiting: {} };
      throw error;
    }
  }

  /**
   * Reads, changes and writes one resource's ledger under its lock, so two
   * daemons claiming at once never both see a free seat.
   */
  private locked<T>(resource: string, change: (ledger: Ledger, now: number) => T): T {
    fs.mkdirSync(this.root, { recursive: true });
    const lock = `${this.file(resource)}.lock`;
    const held = acquire(lock, this.patienceMs);
    try {
      const ledger = this.read(resource);
      const now = this.now().getTime();
      expire(ledger, now);
      const answer = change(ledger, now);
      const temporary = `${this.file(resource)}.${process.pid}.tmp`;
      fs.writeFileSync(temporary, `${JSON.stringify(ledger, null, 2)}\n`);
      fs.renameSync(temporary, this.file(resource));
      return answer;
    } finally {
      held.release();
    }
  }
}

function expire(ledger: Ledger, now: number): void {
  for (const [holder, seat] of Object.entries(ledger.holders)) if (seat.expiresAt <= now) delete ledger.holders[holder];
  for (const [holder, waiter] of Object.entries(ledger.waiting)) if (waiter.expiresAt <= now) delete ledger.waiting[holder];
  if (ledger.draining !== undefined && !ledger.holders[ledger.draining]) delete ledger.draining;
}

/** The waiters in the order seats go to them: priority first, then who asked first. */
function queue(ledger: Ledger): string[] {
  return Object.entries(ledger.waiting)
    .sort(([a, one], [b, other]) => other.priority - one.priority || one.since - other.since || a.localeCompare(b))
    .map(([holder]) => holder);
}

/**
 * Takes the lock, waiting while a live owner holds it. The core's lock
 * reclaims one whose owner died — never by age alone, since a slow owner is
 * still an owner — and of the processes that find it dead, one takes it.
 */
function acquire(lock: string, patienceMs: number): HeldLock {
  for (const until = Date.now() + patienceMs; Date.now() < until;) {
    const held = takeLock(lock, { graceMs: UNOWNED_STALE_MS });
    if (held) return held;
    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 5);
  }
  throw new Error(`the lease lock ${lock} stayed taken; remove it if no amy is running`);
}

/**
 * A name as one path segment: escaped, its dots too, so a scenario, a step,
 * a unit or a resource named `..` stays a file in its own directory rather
 * than reaching the one above it.
 */
export function segment(name: string): string {
  return encodeURIComponent(name).replace(/\./g, "%2E");
}

import path from "node:path";
import { OperationScope, defineOperation, fail, scopeOf } from "@amykit/core";
import { z } from "zod";
import { blocking, holds } from "./assertions.js";
import { PROOFS_DIRECTORY, ProofStore } from "./proof.js";

/**
 * Where an operation finds the proofs. An operation is handed its profile's
 * directory, not the project's artifact root; a project's profile lives at
 * `projects/<project>/<profile>` and its artifact root beside it, which is
 * where the proving phase writes. Any other profile keeps them in its own.
 */
export function proofsOfScope(scope: Pick<OperationScope, "state">): ProofStore {
  const project = path.dirname(scope.state);
  const inProject = path.basename(path.dirname(project)) === "projects";
  return new ProofStore(path.join(inProject ? path.join(project, "artifacts") : scope.state, PROOFS_DIRECTORY));
}

const status = z.enum(["passed", "failed", "unsupported"]);

const assertionInput = z.object({
  id: z.string().min(1),
  criterion: z.string().min(1).optional(),
  status,
  why: z.string().optional(),
});

const proofOutput = z.object({
  unit: z.string(),
  scenario: z.string(),
  outcome: z.enum(["proven", "refused"]),
  refused: z.string().optional(),
  ranBy: z.string(),
  manual: z.boolean(),
  against: z.array(z.string()),
  codeDigest: z.string().nullable(),
  briefRevision: z.number(),
  at: z.string(),
  assertions: z.array(assertionInput),
});

/**
 * A run a person did by hand, recorded as the proof. The record makes it a
 * proof, not who ran it: it names the scenario, each assertion's status,
 * who ran it and what it ran against.
 */
const recordProof = defineOperation({
  id: "prove.record",
  domain: "prove",
  summary: "Record a scenario a person ran by hand as the unit's proof",
  description:
    "Writes the proof record the proving phase writes, beside the briefs, with `manual` set and the person who ran it named. " +
    "Each assertion is given as `id=status`; an unsupported one blocks completion like a failed one. Runs nothing itself.",
  input: z.object({
    unit: z.string().min(1).describe("the unit proved: the brief's id"),
    scenario: z.string().min(1).describe("the scenario that was run"),
    by: z.string().min(1).describe("who ran it"),
    assertion: z.array(z.string()).min(1).describe("each assertion's status, as `id=passed`, `id=failed` or `id=unsupported`; `id@criterion=status` names the criterion it answers"),
    against: z.array(z.string()).default([]).describe("what it ran against: an environment, an account, a build"),
    digest: z.string().optional().describe("the digest of the code it proved, when the unit has code"),
    revision: z.number().int().min(0).describe("the brief revision it proved"),
  }),
  output: proofOutput,
  errors: { "prove.assertion": { description: "an assertion is not written as `id=status`" } },
  writes: [],
  http: { method: "post", path: "/prove/proofs", status: 201 },
  cli: { words: ["prove", "record"], positional: ["unit"] },
  examples: [{
    summary: "a person proved the badge by hand",
    input: { unit: "TBO-12", scenario: "paid-invoice-badge", by: "ada", assertion: ["badge@C1=passed"], revision: 3 },
    output: {
      unit: "TBO-12", scenario: "paid-invoice-badge", outcome: "proven", ranBy: "ada", manual: true, against: [], codeDigest: null, briefRevision: 3,
      at: "2026-11-08T12:00:00.000Z", assertions: [{ id: "badge", criterion: "C1", status: "passed" }],
    },
  }],
  async handler(input, context) {
    const assertions = [];
    for (const one of input.assertion) {
      const [named = "", said = ""] = one.trim().split("=");
      const [id = "", criterion] = named.split("@");
      const read = status.safeParse(said);
      if (!id || criterion === "" || !read.success || one.split("=").length !== 2) {
        return fail("prove.assertion", `\`${one}\` is not \`id=status\`, status one of passed, failed and unsupported`);
      }
      assertions.push({ id, ...(criterion ? { criterion } : {}), status: read.data });
    }
    const proof = {
      unit: input.unit,
      scenario: input.scenario,
      outcome: holds(assertions) ? "proven" as const : "refused" as const,
      ...(holds(assertions) ? {} : { refused: blocking(assertions).join("; ") }),
      assertions,
      ranBy: input.by,
      manual: true,
      against: input.against,
      codeDigest: input.digest ?? null,
      briefRevision: input.revision,
      at: new Date().toISOString(),
    };
    proofsOfScope(scopeOf(context, "prove.record")).write(proof);
    return proof;
  },
});

/** Where a unit stands: proven for the code and brief it is at, or why not. */
const showStanding = defineOperation({
  id: "prove.show",
  domain: "prove",
  summary: "Say whether a unit is proven for the code and brief it is at now",
  description: "Reads the unit's proof record. A proof of other code or of another brief revision does not count, and the unit is unproven again.",
  input: z.object({
    unit: z.string().min(1).describe("the unit: the brief's id"),
    digest: z.string().optional().describe("the digest of the code as it is now"),
    revision: z.number().int().min(0).describe("the brief revision as it is now"),
  }),
  output: z.object({
    proven: z.boolean().describe("proven"),
    why: z.string().optional().describe("why not"),
    proof: proofOutput.optional(),
  }),
  writes: [],
  http: { method: "get", path: "/prove/proofs/{unit}" },
  cli: { words: ["prove", "show"], positional: ["unit"] },
  examples: [{
    summary: "a unit whose code moved since its proof",
    input: { unit: "TBO-12", digest: "b2", revision: 3 },
    output: { proven: false, why: "the proof certified code a1, and the code is b2 now" },
  }],
  async handler(input, context) {
    const standing = proofsOfScope(scopeOf(context, "prove.show")).standing(input.unit, { codeDigest: input.digest ?? null, briefRevision: input.revision });
    return standing.proven
      ? { proven: true, proof: { ...standing.proof, assertions: [...standing.proof.assertions], against: [...standing.proof.against] } }
      : { proven: false, why: standing.why, ...(standing.proof ? { proof: { ...standing.proof, assertions: [...standing.proof.assertions], against: [...standing.proof.against] } } : {}) };
  },
});

export const proofOperations = [recordProof, showStanding];

import path from "node:path";
import {
  ActionContext,
  BriefStore,
  Commands,
  ConfigOf,
  ConfigSchema,
  Conversation,
  Harness,
  MountedOperation,
  Moved,
  Notifier,
  OPERATIONS_COLLECTION,
  Operation,
  WorkflowActionScope,
  WorkflowPieceContext,
  defineWorkflow,
  optional,
  port,
  unitOf,
} from "@amykit/core";
import { StepResult } from "./assertions.js";
import { Effect, Observation, Policy, ProveRecord, decide, stepsBlocking, verdictOf } from "./decide.js";
import { ensure, readFixtures } from "./fixtures.js";
import { Leases } from "./lease.js";
import { proofOperations } from "./operations.js";
import { PROOFS_DIRECTORY, ProofStore } from "./proof.js";
import { bringUp, commandsNamed, readResources, takeDown } from "./resources.js";
import { SCENARIO_SECTION, checkScenario, readScenario, scenarioText } from "./scenario.js";
import { OfferedOperation, Replays, checkUntil, runAgent, runDeterministic, untilMissed } from "./steps.js";

export const configSchema = {
  resources: {
    type: "record",
    default: {},
    description: "what a scenario runs against, by name: `{ capacity, up, check, down }`, each a command the commands port allows. `check` is required",
  },
  fixtures: {
    type: "record",
    default: {},
    description: "states a scenario starts from, shared by name: `{ ensure: [{ check: { operation, input, expect }, act: { operation, input } }] }`",
  },
  digest: {
    type: "string",
    default: "",
    description: "the command, by the name the commands port allows, that prints the digest of the code a proof certifies. Empty where the unit has no code",
  },
  "policy.leaseTtlMs": { type: "number", default: 10 * 60 * 1000, description: "how long a seat on a resource lasts without its run renewing it" },
  "policy.seatRetryMs": { type: "number", default: 30 * 1000, description: "how long a run waits before asking again for a seat or a scenario" },
  "policy.askEveryMs": { type: "number", default: 60 * 1000, description: "how often a run waiting on a person looks for the answer" },
  "policy.fixtureDeadlineMs": { type: "number", default: 24 * 60 * 60 * 1000, description: "how long a person has to make a fixture hold before the run gives up" },
} satisfies ConfigSchema;

type Settings = ConfigOf<typeof configSchema>;

export const needs = {
  brief: port<BriefStore>(),
  notifier: port<Notifier>(),
  conversation: optional<Conversation>(),
  agent: optional<Harness>(),
  commands: optional<Commands>(),
};

type Scope = WorkflowPieceContext<typeof configSchema, Policy, typeof needs>;
type ActionScope = WorkflowActionScope<typeof configSchema, Policy, typeof needs>;
type Work = ActionContext<ProveRecord, Observation>;

/** Where a mount keeps its proofs: the project's artifact root, beside the briefs, or the profile's own state. */
export function proofsAt(paths: { readonly state: string; readonly profile?: string; readonly artifacts?: string }): string {
  return path.join(paths.artifacts ?? paths.profile ?? paths.state, PROOFS_DIRECTORY);
}

/**
 * Who holds a seat: the run, named by the profile it runs in. A work id is
 * unique only inside its profile, and two projects can both be proving
 * `TBO-1/PROVE#1` against one account.
 */
export function holderOf(paths: { readonly state: string; readonly profile?: string }, record: { readonly id: string }): string {
  return `${paths.profile ?? paths.state}#${record.id}`;
}

/** The machine's leases, under Amy home: shared by every project and profile. */
export function leasesAt(home: string): string {
  return path.join(home, "leases");
}

function stores(scope: Scope) {
  const proofs = new ProofStore(proofsAt(scope.ctx.paths));
  return {
    proofs,
    leases: new Leases(leasesAt(scope.ctx.paths.state), scope.ctx.now),
    replays: new Replays(path.join(proofs.directory, "replays")),
  };
}

/** The operations an agent step may call, with their input schemas, as the contract describes them. */
function offeredTo(scope: Scope): OfferedOperation[] {
  return [...scope.ctx.contributions(OPERATIONS_COLLECTION).entries()]
    .map(([id, entry]) => {
      const operation = (entry as MountedOperation).operation as unknown as Operation;
      return { id, input: operation.input["~standard"].jsonSchema.input({ target: "draft-2020-12" }) as Record<string, unknown> };
    })
    .sort((one, other) => one.id.localeCompare(other.id));
}

function ownerOf(scope: Scope, id: string): string | undefined {
  return (scope.ctx.contributions(OPERATIONS_COLLECTION).get(id) as MountedOperation | undefined)?.owner;
}

async function observe(scope: Scope, record: ProveRecord): Promise<Observation> {
  const unit = unitOf(record);
  const now = scope.ctx.now().toISOString();
  const { leases } = stores(scope);
  const lost = (record.held ?? []).filter((resource) => !leases.holds(resource, holderOf(scope.ctx.paths, record)));
  let read: Pick<Observation, "scenario" | "problems" | "briefRevision"> = { problems: [], briefRevision: record.briefRevision ?? 0 };
  if (record.state === "READING") {
    const brief = await scope.ports.brief.get(unit);
    const text = scenarioText(brief);
    const scenario = text === undefined ? { problems: [`it has no \`${SCENARIO_SECTION}\` section`] } : readScenario(text);
    read = { ...scenario, briefRevision: brief?.revision ?? 0 };
  }
  let reply: Observation["reply"];
  if (record.state === "ASKING" && record.asking?.thread && scope.ports.conversation) {
    const answers = await scope.ports.conversation.replies({ id: record.asking.thread }, record.asking.askedAt);
    const first = answers.find((one) => one.text.trim() !== "");
    if (first) reply = { author: first.author, text: first.text, at: first.at };
  }
  return { unit, ...read, lost, ...(reply ? { reply } : {}), now };
}

/** Renews every seat the run holds, so a run that is still moving never loses one. */
function renew(scope: ActionScope, record: ProveRecord): void {
  const { leases } = stores(scope);
  for (const resource of record.held ?? []) leases.renew(resource, holderOf(scope.ctx.paths, record), scope.policy.leaseTtlMs);
}

const actions = {
  lease: async (scope: ActionScope, work: Work) => {
    const { leases } = stores(scope);
    const record = work.record;
    const holder = holderOf(scope.ctx.paths, record);
    const needed = [...(record.scenario?.resources ?? [])].sort();
    // In name order, stopping at the first seat not given: every run claims
    // in one order, so no run holding a later resource waits on an earlier
    // one, and two runs crossing their scenarios' orders cannot wait forever.
    const held: string[] = [];
    for (const resource of needed) {
      const claimed = leases.claim({
        resource,
        capacity: scope.policy.resources[resource]!.capacity,
        holder,
        priority: record.input?.priority ?? 0,
        ttlMs: scope.policy.leaseTtlMs,
      });
      if (!claimed.held) break;
      held.push(resource);
    }
    work.outcomes.held = held;
  },

  renew: async (scope: ActionScope, work: Work) => renew(scope, work.record),

  prepare: async (scope: ActionScope, work: Work) => {
    renew(scope, work.record);
    if (work.record.digest === undefined) work.outcomes.digest = await digestOf(scope);
    if (!(await broughtUp(scope, work))) return;
    if (!(await fixturesHold(scope, work))) return;
    work.outcomes.prepared = true;
  },

  "run-step": async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "run-step" }>) => {
    renew(scope, work.record);
    const record = work.record;
    const step = record.scenario?.steps.find((one) => one.id === effect.step);
    if (!step) throw new Error(`the scenario has no step \`${effect.step}\``);
    const { replays } = stores(scope);
    const operate = scope.operate;
    let result: StepResult | undefined;
    if (step.kind === "deterministic") result = await runDeterministic(step, { operate });
    else if (step.kind === "agent") {
      const agent = scope.ports.agent;
      const ran = await runAgent(record.scenario!.name, step, {
        operate,
        replays,
        offered: offeredTo(scope),
        ...(agent ? { ask: (prompt: string) => agent.ask(prompt, scope.ctx.paths.profile ?? scope.ctx.paths.state, { workId: record.id, step: step.id }) } : {}),
      });
      result = ran.result;
      work.outcomes.agentCalls = { ...record.agentCalls, [step.id]: [...ran.calls] };
    } else if (step.kind === "wait-until") {
      const since = record.untilSince?.[step.id] ?? scope.ctx.now().toISOString();
      const checked = await checkUntil(step, { operate });
      // Measured once the check answered: a check that only finishes past
      // the deadline is past it, whatever it found.
      const late = scope.ctx.now().getTime() - Date.parse(since) > step.deadlineMs;
      if (late) result = untilMissed(step, checked.result);
      else if (checked.holds) result = checked.result;
      else work.outcomes.untilSince = { ...record.untilSince, [step.id]: since };
    }
    if (result) work.outcomes.result = { step: step.id, result };
  },

  ask: async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "ask" }>) => {
    const record = work.record;
    renew(scope, record);
    const unit = unitOf(record);
    const now = scope.ctx.now();
    const deadlineAt = new Date(now.getTime() + effect.deadlineMs).toISOString();
    const about = effect.step ? `the step \`${effect.step}\`` : `the fixture \`${effect.fixture}\``;
    let thread: string | undefined;
    if (scope.ports.conversation) {
      const opened = await scope.ports.conversation.open(unit, `Proving ${unit}`);
      await scope.ports.conversation.post(opened, { text: `${effect.question}\n\n(${about} of \`${record.scenario?.name}\`; answer before ${deadlineAt})` });
      thread = opened.id;
    }
    const held = record.held ?? [];
    await scope.ports.notifier.announce({
      workId: record.id,
      state: "ASKING",
      text: `The proof of ${unit} stopped at ${about} and waits on you${thread ? " in its thread" : ""}: ${effect.question}\n` +
        `It holds ${held.length > 0 ? held.map((one) => `\`${one}\``).join(", ") : "no resource"} until you answer, or until ${deadlineAt}.`,
    });
    work.outcomes.asking = {
      ...(effect.step ? { step: effect.step } : {}),
      ...(effect.fixture ? { fixture: effect.fixture } : {}),
      question: effect.question,
      askedAt: now.toISOString(),
      deadlineAt,
      ...(thread ? { thread } : {}),
    };
  },

  "give-up": async (scope: ActionScope, work: Work) => {
    const asking = work.record.asking;
    await scope.ports.notifier.announce({
      workId: work.record.id,
      state: "ASKING",
      kind: "gave-up",
      text: `Nobody answered \`${asking?.step ?? asking?.fixture}\` of the proof of ${unitOf(work.record)} by ${asking?.deadlineAt}; ` +
        `the proof is refused and ${(work.record.held ?? []).map((one) => `\`${one}\``).join(", ") || "nothing"} is released.`,
    });
  },

  finish: async (scope: ActionScope, work: Work, effect: Extract<Effect, { type: "finish" }>) => {
    const record = work.record;
    const { proofs, replays } = stores(scope);
    const said = await letGo(scope, record);
    if (record.scenario) {
      keepReplays(replays, record);
      const called = record.scenario.steps.flatMap((one) => (one.kind === "deterministic" || one.kind === "wait-until" ? [one.operation] : []));
      const owners = [...new Set(called.map((id) => ownerOf(scope, id)).filter((owner): owner is string => owner !== undefined))];
      proofs.write({
        unit: unitOf(record),
        scenario: record.scenario.name,
        outcome: effect.outcome,
        ...(effect.outcome === "refused" ? { refused: effect.why } : {}),
        assertions: verdictOf(record),
        ranBy: "amy",
        manual: false,
        against: [...(record.held ?? []), ...owners],
        codeDigest: record.digest ?? null,
        briefRevision: record.briefRevision ?? 0,
        at: scope.ctx.now().toISOString(),
      });
    }
    for (const line of said) await scope.announce(line);
  },
};

/**
 * Takes down what the run brought up and gives back its seats. A resource
 * other runs still hold stays up: only its last holder takes it down, and no
 * seat is given while it does.
 */
async function letGo(scope: ActionScope, record: ProveRecord): Promise<string[]> {
  const { leases } = stores(scope);
  const holder = holderOf(scope.ctx.paths, record);
  const said: string[] = [];
  for (const name of record.scenario?.resources ?? []) {
    if ((record.up ?? []).includes(name) && leases.leaveLast(name, holder, scope.policy.leaseTtlMs)) {
      const failed = await takeDown(name, scope.policy.resources[name]!, scope.ports.commands!);
      if (failed) said.push(failed);
    }
    leases.release(name, holder);
  }
  return said;
}

/**
 * An agent step's calls become its replay only when every assertion on the
 * step passed; a replay whose step's assertions failed is forgotten, so the
 * next run asks the agent again rather than repeating a wrong attempt.
 */
function keepReplays(replays: Replays, record: ProveRecord): void {
  const scenario = record.scenario!;
  const verdict = verdictOf(record);
  for (const step of scenario.steps) {
    if (step.kind !== "agent") continue;
    const ids = new Set(scenario.assertions.filter((one) => one.step === step.id).map((one) => one.id));
    const passed = record.results?.[step.id]?.status === "done" && verdict.filter((one) => ids.has(one.id)).every((one) => one.status === "passed");
    const calls = record.agentCalls?.[step.id] ?? [];
    if (passed && calls.length > 0) replays.put(scenario.name, step.id, { calls });
    else if (!passed) replays.remove(scenario.name, step.id);
  }
}

/** Brings up every resource the run has not; false, with why, when one would not come up. */
async function broughtUp(scope: ActionScope, work: Work): Promise<boolean> {
  const up = [...(work.record.up ?? [])];
  for (const name of work.record.scenario?.resources ?? []) {
    if (up.includes(name)) continue;
    const brought = await bringUp(name, scope.policy.resources[name]!, scope.ports.commands!);
    if (!brought.ok) {
      work.outcomes.up = brought.started ? [...up, name] : up;
      work.outcomes.failed = brought.why;
      return false;
    }
    up.push(name);
  }
  work.outcomes.up = up;
  return true;
}

/**
 * Ensures every fixture; false when one is missing or needs a person. A
 * person's answer is not taken for the state: the fixture is read again, and
 * asked again while it still does not hold.
 */
async function fixturesHold(scope: ActionScope, work: Work): Promise<boolean> {
  for (const name of work.record.scenario?.fixtures ?? []) {
    const fixture = scope.policy.fixtures[name];
    if (!fixture) {
      work.outcomes.failed = `the scenario starts from the fixture \`${name}\`, which no configured fixture is`;
      return false;
    }
    const ensured = await ensure(name, fixture, scope.operate);
    if (!ensured.holds) {
      work.outcomes.fixtureAsk = { fixture: name, question: ensured.ask };
      return false;
    }
  }
  return true;
}

async function digestOf(scope: ActionScope): Promise<string | null> {
  const name = scope.config.digest;
  if (!name) return null;
  const ran = await scope.ports.commands!.run(name);
  if (!ran.ok) throw new Error(`the digest command \`${name}\` failed (exit ${ran.exitCode ?? "killed"}): ${ran.output}`);
  return ran.output.trim();
}

/** The record fields an action's outcome lands in, under the same names. */
const FOLDED = ["held", "up", "digest", "failed", "fixtureAsk", "prepared", "untilSince", "asking", "agentCalls"] as const;

/** Folds what the actions found onto the record, and what leaving a state lets go of. */
function remember(record: ProveRecord, outcomes: Record<string, unknown>, observation: Observation, moved: Moved | null): ProveRecord {
  // The record arrives already moved: where it came from is what `moved` says.
  const from = moved?.from ?? record.state;
  let next = folded(record, outcomes);
  if (from === "READING" && next.state !== "READING" && observation.scenario) {
    next = { ...next, scenario: observation.scenario, briefRevision: observation.briefRevision };
  }
  if (next.asking?.fixture && !next.fixtureDeadlines?.[next.asking.fixture]) {
    next = { ...next, fixtureDeadlines: { ...next.fixtureDeadlines, [next.asking.fixture]: next.asking.deadlineAt } };
  }
  if (from === "ASKING" && next.state !== "ASKING") next = afterAsking(record, next, observation);
  if (observation.lost.length > 0 && next.state === "LEASING") next = unseated(next, observation);
  return ended(from, record, next, observation);
}

/** The record with what the actions found folded on, each outcome under its field's own name. */
function folded(record: ProveRecord, outcomes: Record<string, unknown>): ProveRecord {
  const next: ProveRecord = { ...record };
  for (const field of FOLDED) if (outcomes[field] !== undefined) Object.assign(next, { [field]: outcomes[field] });
  if (!outcomes.result) return next;
  const { step, result } = outcomes.result as { step: string; result: StepResult };
  return { ...next, results: { ...next.results, [step]: result } };
}

/** On reaching an end, what the run proved, and why it was refused when it was. */
function ended(from: string, before: ProveRecord, after: ProveRecord, observation: Observation): ProveRecord {
  if ((after.state !== "PROVEN" && after.state !== "refused") || from === after.state) return after;
  return { ...after, verdict: { assertions: verdictOf(after), ...(after.state === "refused" ? { refused: refusalOf(from, before, after, observation) } : {}) } };
}

/** Leaving ASKING: a person's answer is the step's result, or the fixture they made hold. */
function afterAsking(before: ProveRecord, after: ProveRecord, observation: Observation): ProveRecord {
  const { asking: _asked, ...next } = after;
  const reply = observation.reply;
  if (reply && before.asking?.step) {
    return { ...next, results: { ...next.results, [before.asking.step]: { status: "done", output: { answer: reply.text, by: reply.author } } } } as ProveRecord;
  }
  if (reply && before.asking?.fixture) {
    const { fixtureAsk: _settled, ...rest } = next;
    return rest as ProveRecord;
  }
  return next as ProveRecord;
}

/**
 * A lease that ran out is a seat somebody else may have taken: the run
 * waits for one again, and prepares and runs from the start once it has it.
 */
function unseated(record: ProveRecord, observation: Observation): ProveRecord {
  // What the steps found belongs to the resources as they were: a seat lost
  // may mean another run took them down, so the scenario starts over.
  const { prepared: _prepared, fixtureAsk: _fixture, asking: _asking, results: _results, untilSince: _until, agentCalls: _calls, ...rest } = record;
  return { ...rest, held: (record.held ?? []).filter((one) => !observation.lost.includes(one)), up: [] } as ProveRecord;
}

function refusalOf(from: string, before: ProveRecord, after: ProveRecord, observation: Observation): string {
  if (after.failed) return after.failed;
  if (from === "ASKING") return `nobody answered \`${before.asking?.step ?? before.asking?.fixture}\` before ${before.asking?.deadlineAt}`;
  if (from === "LEASING") return "the scenario needs a resource no configuration names";
  const failing = [...stepsBlocking(after), ...verdictOf(after).filter((one) => one.status !== "passed").map((one) => `\`${one.id}\` is ${one.status}`)];
  return failing.length > 0 ? failing.join("; ") : `refused at ${observation.now}`;
}

/** The criteria a run answered: each criterion an assertion that passed names. */
function answered(record: ProveRecord): string[] {
  return [...new Set((record.verdict?.assertions ?? verdictOf(record)).flatMap((one) => (one.status === "passed" && one.criterion ? [one.criterion] : [])))];
}

/**
 * The proving workflow: one diagram every scenario walks.
 *
 * Proving is a plugin, and amy stays a state machine that moves work from
 * one state to the next: the core learns no scenario, step, resource or
 * driver. What proves the work is the domain's — the app running, the post
 * published, the call made — so a step reaches the world only through an
 * operation some other mounted plugin offers.
 */
export const plugin = defineWorkflow({
  name: "prove",
  pluginName: "@amykit/plugin-prove",
  configSchema,
  // The resources and fixtures join the policy at mount, read from their own
  // settings: only the numbers are the policy block's.
  policy: {
    leaseTtlMs: configSchema["policy.leaseTtlMs"].default,
    seatRetryMs: configSchema["policy.seatRetryMs"].default,
    askEveryMs: configSchema["policy.askEveryMs"].default,
    fixtureDeadlineMs: configSchema["policy.fixtureDeadlineMs"].default,
  } as Policy,
  needs,
  input: {
    criteria: { type: "string[]", default: [], description: "the criteria the brief settled, which the proof answers" },
    priority: { type: "number", default: 0, description: "the work's priority: the next free seat on a resource goes to the highest" },
  },
  output: {
    PROVEN: (record: ProveRecord) => ({ criteria: answered(record), scenario: record.scenario?.name }),
    refused: (record: ProveRecord) => ({ criteria: answered(record), refused: record.verdict?.refused ?? "the proof did not hold" }),
  },
  brief: {
    sections: [SCENARIO_SECTION],
    check: (record, { operations }) => checkScenario(record, operations),
  },
  runtimePolicy: ({ ports, config, policy }) => {
    const resources = readResources(config.resources);
    if (Object.keys(resources).length > 0 || config.digest) {
      const commands = ports.commands;
      if (!commands) throw new Error("the proving plugin names resources or a digest command, and nothing mounted the commands port that runs them");
      const allowed = new Set(commands.available());
      const named = [...commandsNamed(resources), ...(config.digest ? [{ resource: "digest", command: config.digest }] : [])];
      for (const { resource, command } of named) {
        if (!allowed.has(command)) throw new Error(`\`${resource}\` runs \`${command}\`, which the commands port does not allow: it allows ${[...allowed].map((one) => `\`${one}\``).join(", ") || "nothing"}`);
      }
    }
    return { ...policy, resources, fixtures: readFixtures(config.fixtures) };
  },
  operations: proofOperations,
  // Its own actions, catalogued here so a project calling it as a phase
  // mounts them: none spends an agent the core counts or writes a tracker,
  // and the notifier is the one port each run of them is sure to have.
  catalogue: Object.fromEntries(
    ["lease", "renew", "prepare", "run-step", "ask", "finish", "give-up"].map((name) => [name, { port: "notifier", method: "announce" }]),
  ),
  record: () => ({}),
  discover: async () => [],
  observe,
  actions: actions as never,
  remember: (_scope, record, outcomes, observation, moved) => remember(record, outcomes, observation, moved),
  decide,
});

export type { Settings };

import fs from "node:fs";
import path from "node:path";
import { AssertionResult, blocking, holds } from "./assertions.js";
import { segment } from "./names.js";

/**
 * A proof is a project artifact, not an execution state: one record per unit
 * beside the briefs in the project's artifact root, written by the proving
 * phase and read by the others through this store — never by reading the
 * proving phase's records or queue.
 *
 * The record makes it a proof, not who ran it: a person's manual run is one
 * as much as amy's, saying who ran it and each assertion's status. It names
 * the code digest and the brief revision it proved; when either moves it
 * stops counting.
 */
export interface ProofRecord {
  readonly unit: string;
  readonly scenario: string;
  /** How the run ended: an assertion passing is not a proof when a step of the run failed. */
  readonly outcome: "proven" | "refused";
  /** Why it was refused, when it was. */
  readonly refused?: string;
  readonly assertions: readonly AssertionResult[];
  /** `amy`, or the person who ran it by hand. */
  readonly ranBy: string;
  readonly manual: boolean;
  /** What it ran against: the resources it leased and the plugins whose operations it called. */
  readonly against: readonly string[];
  /** The code it proved, or null where the unit has no code — a published page, a sent message. */
  readonly codeDigest: string | null;
  readonly briefRevision: number;
  readonly at: string;
}

/** What the unit is, as the other phases read it. */
export type Standing =
  | { readonly proven: true; readonly proof: ProofRecord }
  | { readonly proven: false; readonly why: string; readonly proof?: ProofRecord };

/** The directory under the artifact root the proofs are kept in. */
export const PROOFS_DIRECTORY = "proofs";

export class ProofStore {
  constructor(private readonly root: string) {}

  /** The directory proofs live in, for a replay kept beside them. */
  get directory(): string {
    return this.root;
  }

  write(proof: ProofRecord): void {
    fs.mkdirSync(this.root, { recursive: true });
    const file = this.file(proof.unit);
    const temporary = `${file}.${process.pid}.tmp`;
    fs.writeFileSync(temporary, `${JSON.stringify(proof, null, 2)}\n`);
    fs.renameSync(temporary, file);
  }

  get(unit: string): ProofRecord | null {
    try {
      return JSON.parse(fs.readFileSync(this.file(unit), "utf-8")) as ProofRecord;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    }
  }

  /**
   * Whether the unit is proven for the code and brief it is at now. A proof
   * of other code, or of another revision of the brief, does not count, and
   * the unit is unproven again — which is not done.
   */
  standing(unit: string, current: { readonly codeDigest: string | null; readonly briefRevision: number }): Standing {
    const proof = this.get(unit);
    if (!proof) return { proven: false, why: `nothing proved \`${unit}\` yet` };
    if (proof.codeDigest !== current.codeDigest) {
      return { proven: false, proof, why: `the proof certified code ${proof.codeDigest ?? "(none)"}, and the code is ${current.codeDigest ?? "(none)"} now` };
    }
    if (proof.briefRevision !== current.briefRevision) {
      return { proven: false, proof, why: `the proof certified revision ${proof.briefRevision} of the brief, and the brief is at ${current.briefRevision} now` };
    }
    if (proof.outcome !== "proven") return { proven: false, proof, why: `the run was refused: ${proof.refused ?? "no reason recorded"}` };
    if (!holds(proof.assertions)) return { proven: false, proof, why: blocking(proof.assertions).join("; ") || "the proof asserts nothing" };
    return { proven: true, proof };
  }

  private file(unit: string): string {
    return path.join(this.root, `${segment(unit)}.json`);
  }
}

import type { Commands } from "@amykit/core";

/**
 * A resource a scenario runs against. Nothing about an environment is
 * assumed — containers, a Rails or a Clojure app, an account somebody lent:
 * a resource is the commands its person configured to bring it up, check it
 * and take it down, run through the commands port by the names its config
 * allows. The proving plugin names no tool.
 */
export interface Resource {
  /** How many runs may hold it at once. */
  readonly capacity: number;
  /** The command that brings it up; none for a resource that is always there. */
  readonly up?: string;
  /** The command that says it is ready. Required: a resource nothing checks is assumed, not proven. */
  readonly check: string;
  /** The command that takes it down after the run. */
  readonly down?: string;
}

/** Reads the resources a configuration names, refusing at mount one that cannot be checked, naming it. */
export function readResources(raw: Readonly<Record<string, unknown>>): Record<string, Resource> {
  return Object.fromEntries(Object.entries(raw).map(([name, value]) => [name, readResource(name, value)]));
}

function readResource(name: string, value: unknown): Resource {
  if (typeof value !== "object" || value === null || Array.isArray(value)) throw new Error(`the resource \`${name}\` is not a mapping of capacity, up, check and down`);
  const { capacity = 1, up, check, down, ...rest } = value as Record<string, unknown>;
  const extra = Object.keys(rest);
  if (extra.length > 0) throw new Error(`the resource \`${name}\` names ${extra.map((key) => `\`${key}\``).join(", ")}, which a resource does not have: capacity, up, check and down`);
  if (typeof check !== "string" || check.trim() === "") {
    throw new Error(`the resource \`${name}\` names no \`check\` command: a resource nothing checks is assumed, not proven`);
  }
  if (typeof capacity !== "number" || !Number.isInteger(capacity) || capacity < 1) throw new Error(`the resource \`${name}\` has a capacity of ${JSON.stringify(capacity)}; it needs a whole number of seats, at least one`);
  return { capacity, check, ...command(name, "up", up), ...command(name, "down", down) };
}

/** An optional command of a resource, refused when it is there and names nothing. */
function command(name: string, key: "up" | "down", value: unknown): Partial<Pick<Resource, "up" | "down">> {
  if (value === undefined) return {};
  if (typeof value !== "string" || value.trim() === "") throw new Error(`the resource \`${name}\` has a \`${key}\` that names no command`);
  return { [key]: value };
}

/** Every command the resources name, for a refusal when the commands port does not allow one. */
export function commandsNamed(resources: Readonly<Record<string, Resource>>): { readonly resource: string; readonly command: string }[] {
  return Object.entries(resources).flatMap(([resource, one]) => [one.up, one.check, one.down].filter((command): command is string => command !== undefined).map((command) => ({ resource, command })));
}

/** Brings a resource up and checks it; the check's output names why when it is not ready. */
export async function bringUp(name: string, resource: Resource, commands: Commands): Promise<{ readonly ok: true } | { readonly ok: false; readonly why: string; /** Whether its `up` ran, so the end of the run takes it down. */ readonly started: boolean }> {
  if (resource.up) {
    const up = await commands.run(resource.up);
    if (!up.ok) return { ok: false, started: true, why: `the resource \`${name}\` did not come up: \`${resource.up}\` exited ${up.exitCode ?? "killed"}\n${up.output}` };
  }
  const checked = await commands.run(resource.check);
  if (!checked.ok) return { ok: false, started: resource.up !== undefined, why: `the resource \`${name}\` failed its check \`${resource.check}\` (exit ${checked.exitCode ?? "killed"}):\n${checked.output}` };
  return { ok: true };
}

/** Takes a resource down; a failure is said, never thrown, because the run already ended. */
export async function takeDown(name: string, resource: Resource, commands: Commands): Promise<string | undefined> {
  if (!resource.down) return undefined;
  const down = await commands.run(resource.down);
  return down.ok ? undefined : `the resource \`${name}\` did not come down: \`${resource.down}\` exited ${down.exitCode ?? "killed"}\n${down.output}`;
}

import type { BriefOperation, BriefRecord, BriefRefusal } from "@amykit/core";
import { parse as parseYaml } from "yaml";
import { z } from "zod";

/**
 * The scenario a brief settles while grooming: what proves the unit, as data.
 *
 * One proving workflow walks every scenario, so a task needing one request
 * and one needing two apps, a fixture and a person differ here and nowhere
 * else. A step calls an operation a mounted plugin offers, by id: the
 * proving plugin learns no driver, and the core learns no scenario.
 */

/** The brief section the scenario is written in. */
export const SCENARIO_SECTION = "Scenario";

const expectation = z.object({
  /** A dotted path into the operation's output; the whole output when unsaid. */
  path: z.string().min(1).optional(),
  /** The value it must equal; any value present holds when unsaid. */
  equals: z.unknown().optional(),
}).strict();

const operationCall = z.object({
  operation: z.string().min(1),
  input: z.record(z.string(), z.unknown()).default({}),
}).strict();

const step = z.discriminatedUnion("kind", [
  z.object({ id: z.string().min(1), kind: z.literal("deterministic"), operation: z.string().min(1), input: z.record(z.string(), z.unknown()).default({}) }).strict(),
  z.object({ id: z.string().min(1), kind: z.literal("agent"), prompt: z.string().min(1) }).strict(),
  z.object({ id: z.string().min(1), kind: z.literal("human"), ask: z.string().min(1), deadlineMs: z.number().int().positive() }).strict(),
  z.object({
    id: z.string().min(1),
    kind: z.literal("wait-until"),
    operation: z.string().min(1),
    input: z.record(z.string(), z.unknown()).default({}),
    expect: expectation,
    deadlineMs: z.number().int().positive(),
    everyMs: z.number().int().positive().default(1000),
  }).strict(),
]);

const assertion = z.object({
  id: z.string().min(1),
  /** The brief's criterion this assertion answers, when it answers one. */
  criterion: z.string().min(1).optional(),
  step: z.string().min(1),
  path: z.string().min(1).optional(),
  equals: z.unknown().optional(),
}).strict();

const scenarioSchema = z.object({
  name: z.string().min(1),
  resources: z.array(z.string().min(1)).default([]),
  fixtures: z.array(z.string().min(1)).default([]),
  steps: z.array(z.unknown()).min(1),
  assertions: z.array(assertion).min(1),
}).strict();

export type Expectation = z.infer<typeof expectation>;
export type OperationCall = z.infer<typeof operationCall>;
export type Step = z.infer<typeof step>;
export type Assertion = z.infer<typeof assertion>;
export interface Scenario {
  readonly name: string;
  readonly resources: readonly string[];
  readonly fixtures: readonly string[];
  readonly steps: readonly Step[];
  readonly assertions: readonly Assertion[];
}

export const fixtureSchema = z.object({
  ensure: z.array(z.object({
    /** Reads the world: the state holds when its output meets the expectation. */
    check: operationCall.extend({ expect: expectation.default({}) }),
    /** What moves the world to the state, when it differs; a person is asked when there is none. */
    act: operationCall.optional(),
  }).strict()).min(1),
}).strict();
export type Fixture = z.infer<typeof fixtureSchema>;

/** What reading a scenario found: the scenario, or every reason it is not one. */
export type Read = { readonly scenario: Scenario; readonly problems: readonly [] } | { readonly scenario?: undefined; readonly problems: readonly string[] };

/**
 * A step is deterministic unless it says otherwise: one written without a
 * `kind` is read as `deterministic`, so a scenario of plain calls needs no
 * vocabulary beyond the operation and its input.
 */
function withKind(raw: unknown): unknown {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw) || "kind" in raw) return raw;
  return { ...raw, kind: "deterministic" };
}

/** Reads the scenario a brief's section carries, as YAML. */
export function readScenario(text: string): Read {
  let raw: unknown;
  try {
    raw = parseYaml(text);
  } catch (error) {
    return { problems: [`it is not YAML: ${error instanceof Error ? error.message.split("\n")[0] : String(error)}`] };
  }
  const read = scenarioSchema.safeParse(raw);
  if (!read.success) return { problems: read.error.issues.map(issueText) };
  const problems: string[] = [];
  const steps: Step[] = [];
  read.data.steps.forEach((one, at) => {
    const parsed = step.safeParse(withKind(one));
    if (parsed.success) steps.push(parsed.data);
    else problems.push(...parsed.error.issues.map((issue) => `steps.${at}${issue.path.length > 0 ? "." : ""}${issueText(issue)}`));
  });
  const ids = new Set<string>();
  for (const one of steps) {
    if (ids.has(one.id)) problems.push(`the step \`${one.id}\` is named twice`);
    ids.add(one.id);
  }
  for (const one of read.data.assertions) {
    if (!ids.has(one.step)) problems.push(`the assertion \`${one.id}\` reads the step \`${one.step}\`, which the scenario does not have`);
  }
  if (problems.length > 0) return { problems };
  return { scenario: { ...read.data, steps }, problems: [] };
}

function issueText(issue: z.core.$ZodIssue): string {
  return issue.path.length > 0 ? `${issue.path.join(".")}: ${issue.message}` : issue.message;
}

/** The scenario section of a brief, or undefined when the brief does not answer it. */
export function scenarioText(brief: Pick<BriefRecord, "sections"> | null): string | undefined {
  const body = brief?.sections.find((section) => section.name === SCENARIO_SECTION)?.body;
  return body === undefined || body.trim() === "" ? undefined : body;
}

/** The steps that reach the system through an operation, rather than through a person or a model alone. */
function callsTheSystem(scenario: Scenario): boolean {
  return scenario.steps.some((one) => one.kind === "deterministic" || one.kind === "wait-until");
}

/**
 * The brief check the proving phase declares: the scenario reads, calls the
 * system rather than leaving the walkthrough's fake world its only actor, and
 * every step names an operation a mounted plugin offers with an input that
 * operation's schema accepts.
 */
export function checkScenario(brief: Pick<BriefRecord, "sections">, operations: readonly BriefOperation[]): BriefRefusal[] {
  const text = scenarioText(brief);
  if (text === undefined) return [{ section: SCENARIO_SECTION, rule: "the brief names no scenario, so nothing can prove it" }];
  const read = readScenario(text);
  if (!read.scenario) return read.problems.map((rule) => ({ section: SCENARIO_SECTION, rule }));
  const refusals: BriefRefusal[] = [];
  if (!callsTheSystem(read.scenario)) {
    refusals.push({
      section: SCENARIO_SECTION,
      rule: `the scenario \`${read.scenario.name}\` calls no operation, so the walkthrough's fake world would be its only actor — a step has to reach the real system`,
    });
  }
  const offered = new Map(operations.map((one) => [one.id, one.input]));
  for (const one of read.scenario.steps) {
    if (one.kind !== "deterministic" && one.kind !== "wait-until") continue;
    refusals.push(...callRefusals(`the step \`${one.id}\``, one, offered));
  }
  return refusals;
}

/** What is wrong with one call: the operation nothing offers, or the input its schema refuses. */
function callRefusals(who: string, call: OperationCall, offered: ReadonlyMap<string, Readonly<Record<string, unknown>>>): BriefRefusal[] {
  const schema = offered.get(call.operation);
  if (!schema) return [{ section: SCENARIO_SECTION, rule: `${who} calls \`${call.operation}\`, which no mounted plugin offers` }];
  const checked = inputSchema(schema).safeParse(call.input);
  if (checked.success) return [];
  return [{ section: SCENARIO_SECTION, rule: `${who} hands \`${call.operation}\` an input its schema refuses: ${checked.error.issues.map(issueText).join("; ")}` }];
}

function inputSchema(schema: Readonly<Record<string, unknown>>): z.ZodType {
  const { $schema: _dialect, ...rest } = schema;
  return z.fromJSONSchema(rest as Parameters<typeof z.fromJSONSchema>[0]);
}

/** The value at a dotted path, and whether it was there at all. */
export function at(value: unknown, path: string | undefined): { readonly found: boolean; readonly value?: unknown } {
  if (path === undefined) return { found: true, value };
  let here: unknown = value;
  for (const key of path.split(".")) {
    if (typeof here !== "object" || here === null || !Object.hasOwn(here, key)) return { found: false };
    here = (here as Record<string, unknown>)[key];
  }
  return { found: true, value: here };
}

/** Whether an output meets an expectation: the path is there, and equals what it must when that is said. */
export function meets(output: unknown, expectation: Expectation): boolean {
  const found = at(output, expectation.path);
  if (!found.found) return false;
  return expectation.equals === undefined ? found.value !== undefined && found.value !== null && found.value !== false : same(found.value, expectation.equals);
}

/** Whether two values are equal as data: a mapping's keys in any order, an array's items in theirs. */
export function same(one: unknown, other: unknown): boolean {
  if (Array.isArray(one) || Array.isArray(other)) {
    return Array.isArray(one) && Array.isArray(other) && one.length === other.length && one.every((item, at) => same(item, other[at]));
  }
  if (typeof one === "object" && one !== null && typeof other === "object" && other !== null) {
    const keys = Object.keys(one);
    return keys.length === Object.keys(other).length
      && keys.every((key) => Object.hasOwn(other, key) && same((one as Record<string, unknown>)[key], (other as Record<string, unknown>)[key]));
  }
  return Object.is(one, other);
}

import fs from "node:fs";
import path from "node:path";
import type { HarnessReply, Operated } from "@amykit/core";
import { StepResult } from "./assertions.js";
import { OperationCall, Step, meets } from "./scenario.js";
import { segment } from "./names.js";

/**
 * What a step runs through: the mounted operations, and a harness only an
 * agent step ever starts. A deterministic step runs no model; an operation
 * whose own plugin calls one inside it is that plugin's business.
 */
export interface OfferedOperation {
  readonly id: string;
  readonly input: Readonly<Record<string, unknown>>;
}

/** How many turns an agent step may take before it is unsupported: a model that never says done costs without end. */
const AGENT_TURNS = 12;

/** How much of one call's output a turn shows the agent: enough to read refs, not a page dump per turn. */
const SHOWN = 4000;

export interface StepPorts {
  operate(id: string, input: unknown): Promise<Operated>;
  /** Asks the harness; absent where none is mounted, and then an agent step is unsupported. */
  readonly ask?: (prompt: string) => Promise<HarnessReply>;
  readonly replays: Replays;
  /** The operations the agent may call: each id, with the JSON Schema its input is checked against. */
  readonly offered: readonly OfferedOperation[];
}

/** An agent step that passed, kept as the operations it called. */
export interface Replay {
  readonly calls: readonly OperationCall[];
}

/**
 * The replays one scenario keeps, beside the proofs: the next run calls the
 * same operations with no model, and the agent runs again only where the
 * replay breaks.
 */
export class Replays {
  constructor(private readonly root: string) {}

  get(scenario: string, step: string): Replay | null {
    try {
      return JSON.parse(fs.readFileSync(this.file(scenario, step), "utf-8")) as Replay;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    }
  }

  /** Forgets a kept replay: one whose step's assertions failed would pin a wrong attempt. */
  remove(scenario: string, step: string): void {
    fs.rmSync(this.file(scenario, step), { force: true });
  }

  put(scenario: string, step: string, replay: Replay): void {
    const file = this.file(scenario, step);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, `${JSON.stringify(replay, null, 2)}\n`);
  }

  private file(scenario: string, step: string): string {
    return path.join(this.root, segment(scenario), `${segment(step)}.json`);
  }
}

/** One operation call, as a step's result. */
async function call(ports: Pick<StepPorts, "operate">, one: OperationCall): Promise<StepResult> {
  const ran = await ports.operate(one.operation, one.input);
  return ran.ok ? { status: "done", output: ran.output } : { status: "failed", why: `\`${one.operation}\` answered ${ran.error.code}: ${ran.error.message}` };
}

/** Runs a deterministic step: its one operation, no harness. */
export async function runDeterministic(step: Extract<Step, { kind: "deterministic" }>, ports: Pick<StepPorts, "operate">): Promise<StepResult> {
  return call(ports, step);
}

/** One check of a wait-until step: whether it holds now, and what the operation said. */
export async function checkUntil(step: Extract<Step, { kind: "wait-until" }>, ports: Pick<StepPorts, "operate">): Promise<{ readonly holds: boolean; readonly result: StepResult }> {
  const result = await call(ports, step);
  return { holds: result.status === "done" && meets(result.output, step.expect), result };
}

/** What a wait-until step that ran out of time fails with, naming its check. */
export function untilMissed(step: Extract<Step, { kind: "wait-until" }>, last: StepResult | undefined): StepResult {
  const said = last?.status === "done" ? `; it last answered ${JSON.stringify(last.output)}` : last ? `; ${last.why}` : "";
  return {
    status: "failed",
    why: `the check \`${step.operation}\`${step.expect.path ? ` on \`${step.expect.path}\`` : ""} did not hold within ${step.deadlineMs}ms${said}`,
  };
}

/** What an agent step ended with, and the calls that got it there: kept as its replay only once its assertions pass. */
export interface AgentRun {
  readonly result: StepResult;
  readonly calls: readonly OperationCall[];
}

/**
 * Runs an agent step. A replay kept from a run that passed is called first,
 * with no model; the harness is asked only when there is none, or from the
 * call where the replay broke. What the agent cannot settle is unsupported.
 * Nothing is kept here: the run keeps the calls once the step's assertions
 * pass.
 */
export async function runAgent(scenario: string, step: Extract<Step, { kind: "agent" }>, ports: StepPorts): Promise<AgentRun> {
  const kept = ports.replays.get(scenario, step.id);
  const replayed = kept ? await replay(kept, ports) : { ran: [] };
  if (replayed.last && !replayed.broke) return { result: replayed.last, calls: replayed.ran };
  if (!ports.ask) return unsupported(`the step \`${step.id}\` needs an agent, and no harness is mounted`);
  return turns(step, ports, ports.ask, replayed);
}

/**
 * The agent's turns. Each one shows what every call so far answered, so it
 * can use a ref one call returned in the next; only the calls that worked
 * are kept.
 */
async function turns(
  step: Extract<Step, { kind: "agent" }>,
  ports: StepPorts,
  ask: (prompt: string) => Promise<HarnessReply>,
  replayed: { readonly ran: OperationCall[]; readonly last?: StepResult; readonly broke?: { readonly at: OperationCall; readonly why: string } },
): Promise<AgentRun> {
  const ran: OperationCall[] = [...replayed.ran];
  const seen: Turn[] = replayed.broke ? [{ call: replayed.broke.at, answered: { status: "failed", why: replayed.broke.why } }] : [];
  let last: StepResult | undefined = replayed.broke ? undefined : replayed.last;
  for (let turn = 0; turn < AGENT_TURNS; turn += 1) {
    const reply = await ask(agentPrompt(step, ports.offered, replayed.ran, seen));
    const answer = reply.run.outcome === "completed" ? answerIn(reply.text) : { unsupported: `the agent did not finish \`${step.id}\`: ${reply.run.output || reply.run.outcome}` };
    if (!answer) return unsupported(`the agent answered \`${step.id}\` with nothing amy can read`);
    if ("unsupported" in answer) return unsupported(answer.unsupported);
    if ("done" in answer) return last ? { result: last, calls: ran } : unsupported(`the agent called nothing for \`${step.id}\``);
    const answered = await call(ports, answer.call);
    seen.push({ call: answer.call, answered });
    if (answered.status === "done") {
      ran.push(answer.call);
      last = answered;
    }
  }
  return unsupported(`the agent did not settle \`${step.id}\` in ${AGENT_TURNS} turns`);
}

/** One call an agent made this run, with what it answered. */
interface Turn {
  readonly call: OperationCall;
  readonly answered: StepResult;
}

function unsupported(why: string): AgentRun {
  return { result: { status: "unsupported", why }, calls: [] };
}

/** A kept replay's calls, in order, until one breaks: what ran, the last result, and where it broke. */
async function replay(kept: Replay, ports: Pick<StepPorts, "operate">): Promise<{ ran: OperationCall[]; last?: StepResult; broke?: { readonly at: OperationCall; readonly why: string } }> {
  const ran: OperationCall[] = [];
  let last: StepResult | undefined;
  for (const one of kept.calls) {
    last = await call(ports, one);
    if (last.status !== "done") return { ran, last, broke: { at: one, why: last.why } };
    ran.push(one);
  }
  return { ran, ...(last ? { last } : {}) };
}

function shown(result: StepResult): string {
  const text = result.status === "done" ? JSON.stringify(result.output) : `${result.status}: ${result.why}`;
  return text.length > SHOWN ? `${text.slice(0, SHOWN)}… (${text.length - SHOWN} more characters)` : text;
}

function agentPrompt(step: Extract<Step, { kind: "agent" }>, offered: readonly OfferedOperation[], replayed: readonly OperationCall[], seen: readonly Turn[]): string {
  return [
    `Prove one step of a scenario by calling operations, one at a time, never by changing code: ${step.prompt}`,
    `The operations you may call, each with the JSON Schema of its input:\n${offered.map((one) => `- \`${one.id}\`: ${JSON.stringify(one.input)}`).join("\n") || "(none)"}`,
    ...(replayed.length > 0 ? [`A kept replay already ran these, in order, and they need not run again: ${JSON.stringify(replayed)}.`] : []),
    ...(seen.length > 0 ? [`What each call so far answered, in order:\n${seen.map((one) => `- ${JSON.stringify(one.call)} → ${shown(one.answered)}`).join("\n")}`] : []),
    "Answer with one JSON object as the last thing you say: " +
      '{"call":{"operation":"<id>","input":{...}}} for the next call, {"done":true} once the last call\'s answer is what the step is about, ' +
      'or {"unsupported":"<why>"} when calling them cannot settle it.',
  ].join("\n\n");
}

type Answer = { readonly call: OperationCall } | { readonly done: true } | { readonly unsupported: string };

/** The last JSON object in a reply, read as the next call, done, or why it cannot be settled. */
function answerIn(text: string): Answer | undefined {
  // `lastIndexOf("{", -1)` searches position zero again, so the scan stops
  // explicitly once it has tried the first character.
  for (let start = text.lastIndexOf("{"); start >= 0; start = start === 0 ? -1 : text.lastIndexOf("{", start - 1)) {
    let parsed: unknown;
    try {
      parsed = JSON.parse(text.slice(start, text.lastIndexOf("}") + 1));
    } catch {
      continue;
    }
    return readAnswer(parsed);
  }
  return undefined;
}

function readAnswer(parsed: unknown): Answer | undefined {
  if (typeof parsed !== "object" || parsed === null) return undefined;
  const { call: next, done, unsupported: why } = parsed as { call?: unknown; done?: unknown; unsupported?: unknown };
  if (typeof why === "string") return { unsupported: why };
  if (done === true) return { done: true };
  if (typeof next !== "object" || next === null || typeof (next as OperationCall).operation !== "string") return undefined;
  const input = (next as { input?: unknown }).input;
  return { call: { operation: (next as OperationCall).operation, input: typeof input === "object" && input !== null && !Array.isArray(input) ? input as Record<string, unknown> : {} } };
}
